        "title": "Đọc hiểu bài 10: Global Trade & Economic Policy",
        "passage": "Mastering the theme of \"Global Trade & Economic Policy\" is a valuable step for every English learner at level C1.\n\nWhen exploring this topic, everyday words such as \"Tariff\" and \"Protectionism\" serve as the foundational building blocks. Language experts recommend that beginners should not merely memorize isolated definitions. Instead, connecting new vocabulary to real-life situations creates lasting memory pathways in the brain.\n\nFor example, when you understand how \"Free trade agreement\" functions within a complete sentence, you gain the confidence to express your thoughts clearly. Studies show that students who spend twenty minutes daily reading and repeating sentences aloud progress twice as fast as passive learners. Consistency, curiosity, and patience are the three essential keys to language mastery.",
        "translation": "Làm chủ chủ đề \"Global Trade & Economic Policy\" là một bước tiến giá trị cho mọi người học tiếng Anh ở trình độ C1.\n\nKhi khám phá chủ đề này, những từ vựng quen thuộc như \"Tariff\" (Hàng rào thuế quan bảo hộ) và \"Protectionism\" (Chủ nghĩa bảo hộ mậu dịch) đóng vai trò là những viên gạch nền tảng. Các chuyên gia ngôn ngữ khuyên rằng người mới bắt đầu không nên chỉ học vẹt các định nghĩa rời rạc. Thay vào đó, việc liên kết từ mới với các tình huống đời thực sẽ tạo ra những đường dẫn ghi nhớ lâu dài trong não bộ.\n\nVí dụ, khi bạn hiểu cách từ \"Free trade agreement\" hoạt động trong một câu hoàn chỉnh, bạn sẽ có được sự tự tin để diễn đạt suy nghĩ một cách rõ ràng. Các nghiên cứu chỉ ra rằng những học viên dành hai mươi phút mỗi ngày để đọc và nhắc lại to các câu mẫu sẽ tiến bộ nhanh gấp đôi so với người học thụ động. Sự kiên trì, lòng tò mò và tính kiên nhẫn chính là ba chìa khóa thiết yếu để làm chủ ngôn ngữ.",
        "questions": "[{\"question\":\"What is the main topic of the reading passage?\",\"options\":[\"The importance and effective methods of mastering Global Trade & Economic Policy\",\"A historical overview of grammatical shifts in modern English communication\",\"The psychological techniques for overcoming anxiety in public speaking\",\"A comparative study on exam preparation strategies versus independent learning\"],\"correctAnswer\":\"The importance and effective methods of mastering Global Trade & Economic Policy\",\"explanation\":\"The passage primarily highlights the value and learning strategies for \\\"Global Trade & Economic Policy\\\".\"},{\"question\":\"What do language experts recommend instead of memorizing isolated definitions?\",\"options\":[\"Translating full paragraphs word-for-word into mother tongue\",\"Focusing exclusively on grammatical formulas without practicing sentences\",\"Reviewing vocabulary lists only once every two weeks\",\"Connecting new vocabulary to real-life situations\"],\"correctAnswer\":\"Connecting new vocabulary to real-life situations\",\"explanation\":\"The passage recommends connecting new vocabulary to real-life situations to create lasting memory pathways.\"},{\"question\":\"According to the passage, how much daily reading practice helps learners progress twice as fast?\",\"options\":[\"One hour every weekend\",\"Twenty minutes daily\",\"Forty-five minutes twice a week\",\"Ten minutes before bedtime\"],\"correctAnswer\":\"Twenty minutes daily\",\"explanation\":\"The author notes that spending twenty minutes daily reading and repeating sentences aloud doubles learning progress.\"},{\"question\":\"In the passage, why is the word \\\"Tariff\\\" highlighted?\",\"options\":[\"It is an advanced idiom reserved only for academic writing\",\"It is primarily used as a formal greeting in business emails\",\"It serves as a foundational building block for the topic Global Trade & Economic Policy\",\"It represents an exceptional irregular verb form to memorize\"],\"correctAnswer\":\"It serves as a foundational building block for the topic Global Trade & Economic Policy\",\"explanation\":\"The text points out that words like \\\"Tariff\\\" serve as foundational building blocks.\"},{\"question\":\"What are the three essential keys to language mastery mentioned in the conclusion?\",\"options\":[\"Speed, repetition, and memorization\",\"Consistency, curiosity, and patience\",\"Fluency, grammar rules, and translation\",\"Confidence, vocabulary breadth, and accent\"],\"correctAnswer\":\"Consistency, curiosity, and patience\",\"explanation\":\"The passage concludes that consistency, curiosity, and patience are the three essential keys.\"}]"
