        "title": "Luyện nghe bài 14: Fronting & Cleft Sentences for Emphasis",
        "transcript": "Hello everyone! My name is Anna. I am 21 years old and I currently live in London. I am a university student studying languages. Today, I am very excited to share my experience with Fronting & Cleft Sentences for Emphasis. In my daily routine, I frequently use the word \"Cleft sentence\" when talking with friends. Yesterday afternoon, I spent one hour practicing \"Fronting\" with my classmates. In addition, knowing how to use \"Focus\" correctly helps me communicate much more naturally. I believe that practicing for fifteen minutes every day is the best secret to becoming confident. Thank you very much for listening!",
        "audioUrl": null,
        "questions": "[{\"question\":\"What is the speaker's name in the audio?\",\"options\":[\"Anna\",\"Laura\",\"Emma\",\"Sarah\"],\"correctAnswer\":\"Anna\",\"explanation\":\"The audio opens with the introduction: \\\"My name is Anna.\\\"\"},{\"question\":\"How old is the speaker and where does she live?\",\"options\":[\"22 years old, living in Manchester\",\"21 years old, living in London\",\"23 years old, living in Bristol\",\"20 years old, living in Edinburgh\"],\"correctAnswer\":\"21 years old, living in London\",\"explanation\":\"In the audio, the speaker says: \\\"I am 21 years old and I currently live in London.\\\"\"},{\"question\":\"What is the speaker's current occupation or role?\",\"options\":[\"Part-time language peer tutor\",\"Graduate teaching assistant in linguistics\",\"Intern at an international cultural exchange center\",\"University student studying languages\"],\"correctAnswer\":\"University student studying languages\",\"explanation\":\"The speaker clearly states: \\\"I am a university student studying languages.\\\"\"},{\"question\":\"Which vocabulary word did the speaker practice yesterday afternoon?\",\"options\":[\"Focus\",\"Cleft sentence\",\"Fronting\",\"Prominence\"],\"correctAnswer\":\"Fronting\",\"explanation\":\"The speaker mentions: \\\"Yesterday afternoon, I spent one hour practicing 'Fronting' with my classmates.\\\"\"},{\"question\":\"According to the speaker, what is the best secret to becoming confident?\",\"options\":[\"Practicing for fifteen minutes every day\",\"Writing complex essays before practicing basic conversation\",\"Reviewing grammar rules once a month\",\"Memorizing fifty words without speaking practice\"],\"correctAnswer\":\"Practicing for fifteen minutes every day\",\"explanation\":\"The speaker recommends: \\\"practicing for fifteen minutes every day is the best secret to becoming confident.\\\"\"}]"
